    private final String nation;
    private final String code;

    Nationality(String nation, String code) {
        this.nation = nation;
        this.code = code;
    }

    public String getNation() {
        return nation;
    }
    public String getCodeM() {
        return code;
    }
    public static String findByName(String code) {
        String result = null;
        for (Nationality nationality : values()) {
            if (nationality.code.equals(code)) {
                result = nationality.nation;
                break;
            }
        }
        return result;
    }
